				expectPackfile = ready
			case "shallow-info\n":
				expectPackfile = true
				if err := SkipSection(reader); err != nil {
					return err
				}
			default:
				return fmt.Errorf("unexpected protocol v2 fetch section %q", strings.TrimSpace(line))
			}
		}
	}
}

